                ["Verwendungsbaum nach oben"] = "Árbol de uso hacia arriba",
                ["Links eine Komponente anklicken."] = "Haga clic en un componente a la izquierda.",
                ["Höchstens 4 Stufen und 25 Einträge je Stufe."] = "Como máximo 4 niveles y 25 entradas por nivel.",
                ["Endprodukte mit vererbtem Risiko"] = "Productos finales con riesgo heredado",
                ["Komponenten darunter, die nur einen Lieferanten haben oder überfällig sind."] = "Componentes inferiores con un solo proveedor o vencidos.",
                ["Komponenten darunter"] = "Componentes inferiores",
                ["Logistik live"] = "Logística en vivo",
