                ["nicht erreichbar"] = "i paarritshëm",
                ["Ziele"] = "Objektivat",
                ["Linie: Antwortzeit der letzten 24 Stunden. Zahl: Anteil erfolgreicher Prüfungen in 24 Stunden. SAP nur über den öffentlichen Ping ohne Anmeldung, HANA nur Port-Test."] = "Vija: koha e përgjigjes e 24 orëve të fundit. Numri: pjesa e kontrolleve të suksesshme në 24 orë. SAP vetëm përmes ping-ut publik pa hyrje, HANA vetëm test porte.",
                ["Verfügbarkeit je Stunde, letzte 7 Tage"] = "Disponueshmëria për orë, 7 ditët e fundit",
                ["Jedes Feld ist eine Stunde. Grün: alle Prüfungen erfolgreich, rot: keine, grau: noch nicht geprüft."] = "Çdo fushë është një orë. Jeshile: të gjitha kontrollet me sukses, e kuqe: asnjë, gri: ende pa kontrolluar.",
                ["teilweise"] = "pjesërisht",
                ["keine Prüfung"] = "pa kontroll",
                ["SAP-Frühwarnung, letzte 30 Tage"] = "Paralajmërimi i hershëm i SAP, 30 ditët e fundit",
                ["Linie: Antwortzeit des SAP-Pings je Tag. Balken: Warnungen und Fehler der SAP-Abrufe des Cockpits (Einkauf, HR, Logistik, Journal). Steigen beide, wird SAP langsam, bevor es steht."] = "Vija: koha e përgjigjes së ping-ut të SAP për ditë. Shtyllat: paralajmërime dhe gabime të thirrjeve SAP të cockpit-it (blerje, HR, logjistikë, ditar). Nëse rriten të dyja, SAP ngadalësohet para se të ndalojë.",
                ["Warnungen/Fehler"] = "Paralajmërime/gabime",
                ["SAP-Antwortzeit (ms)"] = "Koha e përgjigjes së SAP (ms)",
                ["Höchstwert"] = "Vlera maksimale",
                ["Exportläufe seit Juni"] = "Ekzekutimet e eksportit që nga qershori",
                ["davon fehlgeschlagen"] = "nga të cilat të dështuara",
                ["Ursache Netz"] = "Shkaku: rrjeti",
                ["Ursache Daten oder Quelle"] = "Shkaku: të dhënat ose burimi",
                ["Exportläufe je Standort"] = "Ekzekutimet e eksportit për vend",
                ["Jeder Punkt ist ein Lauf. „Netz“ heisst: die Fehlermeldung deutet auf eine Verbindung, oder das Ziel war zur selben Zeit nicht erreichbar (Prüfungen erst seit dem Start der Netzwerkprüfung)."] = "Çdo pikë është një ekzekutim. „Rrjeti“ do të thotë: mesazhi i gabimit tregon një lidhje, ose objektivi nuk ishte i arritshëm në të njëjtën kohë (kontrolle vetëm që nga nisja e monitorimit të rrjetit).",
                ["erfolgreich"] = "e suksesshme",
                ["Netz"] = "Rrjeti",
                ["Daten oder Quelle"] = "Të dhëna ose burim",
                ["Standorte nach Kritikalität"] = "Vendet sipas kritikalitetit",
                ["Umsatz 2025 in CHF (Kurs 31.12.2025), Abhängigkeit, Exportfehler und Verfügbarkeit des Ziels in 24 Stunden. Oben steht, wo ein Ausfall am meisten kostet."] = "Qarkullimi 2025 në CHF (kursi 31.12.2025), varësia, dështimet e eksportit dhe disponueshmëria e objektivit në 24 orë. Sipër është aty ku ndërprerja kushton më shumë.",
                ["Läufe"] = "Ekzekutime",
                ["davon Netz"] = "nga të cilat rrjeti",
                ["Ziel 24 h"] = "Objektivi 24 orë",
                ["Letzte Fehler"] = "Gabimet e fundit",
                ["Zertifikate: Restlaufzeit"] = "Certifikatat: koha e mbetur",
                ["Aus dem TLS-Handshake der letzten Prüfung. Rot unter 30 Tagen, gelb unter 90."] = "Nga handshake TLS i kontrollit të fundit. E kuqe nën 30 ditë, e verdhë nën 90.",
                ["Noch keine Prüfung mit Zertifikat gespeichert."] = "Ende nuk është ruajtur asnjë kontroll me certifikatë.",
                ["Tage"] = "ditë",
                ["DNS und Verschlüsselung"] = "DNS dhe enkriptimi",
                ["Das SAP-Gateway wird über HTTP ohne Verschlüsselung angesprochen (Port 8000). Benutzer und Passwort der OData-Abrufe gehen damit unverschlüsselt durchs interne Netz."] = "Gateway-i i SAP thirret përmes HTTP pa enkriptim (porti 8000). Përdoruesi dhe fjalëkalimi i thirrjeve OData kalojnë kështu të paenkriptuar nëpër rrjetin e brendshëm.",
                ["HANA und eigene Ziele werden nur per Port geprüft; ob dort verschlüsselt wird, sieht diese Prüfung nicht."] = "HANA dhe objektivat e veta kontrollohen vetëm me port; ky kontroll nuk e shikon nëse atje enkriptohet.",
                ["AD-Computerkonten"] = "Llogaritë e kompjuterëve AD",
                ["Abgeschaltet, bis die IT zustimmt. Einschalten mit NetworkProbe:AdEnabled = true in appsettings.json. Gelesen werden nur Computerkonten, keine Personen."] = "I çaktivizuar derisa IT të pajtohet. Aktivizohet me NetworkProbe:AdEnabled = true në appsettings.json. Lexohen vetëm llogari kompjuterësh, jo persona.",
                ["Computerkonten"] = "Llogaritë e kompjuterëve",
                ["deaktiviert"] = "i çaktivizuar",
                ["aktiv, aber 90 Tage ohne Anmeldung"] = "aktiv, por 90 ditë pa hyrje",
                ["Computer"] = "Kompjuterë",
                ["Aktive Konten ohne Anmeldung seit 90 Tagen"] = "Llogari aktive pa hyrje për 90 ditë",
                ["nie"] = "kurrë",
                ["Noch nicht möglich, braucht eine Freigabe von IT und Datenschutz: wer mit wem spricht (Firewall-Logs), DHCP-Geräte ohne AD-Konto und Konten von Ausgetretenen."] = "Ende nuk është e mundur, kërkon miratimin e IT dhe mbrojtjes së të dhënave: kush flet me kë (regjistrat e firewall-it), pajisje DHCP pa llogari AD dhe llogari të të larguarve.",
                ["Verbindungsabbrüche je Netzbereich, letzte 7 Tage"] = "Ndërprerjet e lidhjes sipas segmentit të rrjetit, 7 ditët e fundit",
                ["Gezählt wird, wie oft die Browser-Verbindung zum Cockpit abreisst. Viele Abbrüche je Sitzung in einem Bereich deuten auf schwaches WLAN. Gespeichert wird nur der Bereich (/24), keine Person und keine volle Adresse."] = "Numërohet sa herë ndërpritet lidhja e shfletuesit me cockpit-in. Shumë ndërprerje për seancë në një segment tregojnë Wi-Fi të dobët. Ruhet vetëm segmenti (/24), asnjë person dhe asnjë adresë e plotë.",
                ["Noch keine Verbindungen erfasst. Die Zählung beginnt mit dem Deploy."] = "Ende nuk janë regjistruar lidhje. Numërimi fillon me deploy-n.",
                ["Sitzungen"] = "Seancat",
                ["Abbrüche"] = "Ndërprerjet",
                ["Zahl rechts: Abbrüche je Sitzung"] = "Numri në të djathtë: ndërprerje për seancë",
                ["Abbrüche nach Tageszeit"] = "Ndërprerjet sipas orës së ditës",
                ["Eigene Prüfziele"] = "Objektiva të veta të kontrollit",
                ["Zum Beispiel Rückmeldeterminals. Geprüft wird nur der Port, alle 5 Minuten. Mit Arbeitsplatz zeigt die Seite neben dem Netz die letzte Rückmeldung aus Logistik live: Terminal erreichbar und keine Rückmeldung heisst eher Stillstand, Terminal nicht erreichbar eher Netz."] = "Për shembull terminale konfirmimi. Kontrollohet vetëm porti, çdo 5 minuta. Me vendin e punës faqja tregon pranë rrjetit konfirmimin e fundit nga Logistik live: terminal i arritshëm pa konfirmim tregon më shumë ndalesë, terminal i paarritshëm më shumë rrjetin.",
                ["Rechnername oder IP"] = "Emri i hostit ose IP",
                ["Arbeitsplatz (optional)"] = "Vendi i punës (opsionale)",
                ["Hinzufügen"] = "Shto",
                ["Noch keine eigenen Ziele. Eine Liste Terminal und Arbeitsplatz kommt von der IT."] = "Ende nuk ka objektiva të veta. Një listë terminali dhe vendi i punës vjen nga IT.",
                ["Letzte Rückmeldung"] = "Konfirmimi i fundit",
                ["Rückmeldungen erscheinen, solange Logistik live irgendwo offen ist."] = "Konfirmimet shfaqen për sa kohë Logistik live është e hapur diku.",
                ["Verwendung & Risiko"] = "Përdorimi dhe rreziku",
